export const SCHEMA_FILE = path.resolve(here, "..", "..", "schemas", "performance_command_v1.schema.json");
export const SCHEMA = JSON.parse(fs.readFileSync(SCHEMA_FILE, "utf8"));
// P08: v1.1.0 adds effect kinds whose executors exist (VisemeSync, ExpressionTransitionTraversed); a 1.0.0 packet validates against the unchanged P06 schema
